26	@Mapper(uses = PetMapper.class)
27	public interface OwnerMapper {
28	
29	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
30	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
31	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
32	    @Mapping(target = "initials", expression = "java(initials(owner))")
33	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
34	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
35	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
36	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
37	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
38	    @Mapping(target = "locality", expression = "java(locality(owner))")
39	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
40	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
41	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
42	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
43	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
44	    @Mapping(target = "possibleDuplicate", expression = "java(possibleDuplicate(owner))")
45	    OwnerDto toOwnerDto(Owner owner);
46	
47	    Owner toOwner(OwnerDto ownerDto);
48	
49	    /** The owner's canonical API path: '/api/owners/' followed by the owner's id. */
50	    default String selfLink(Owner owner) {
51	        return "/api/owners/" + owner.getId();
52	    }
53	
54	    /** The owner's salutation: '&lt;title&gt; &lt;lastName&gt;' when a title was supplied,
55	     * otherwise just the last name. */
56	    default String salutation(Owner owner) {
57	        String title = owner.getTitle();
58	        return (title == null || title.isBlank()) ? owner.getLastName() : title + " " + owner.getLastName();
59	    }
60	
61	    /** Format an owner's name as 'LastName, FirstName' for display. */
62	    default String displayName(Owner owner) {
63	        return owner.getLastName() + ", " + owner.getFirstName();
64	    }
65	
66	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
67	    default String initials(Owner owner) {
68	        return initial(owner.getFirstName()) + initial(owner.getLastName());
69	    }
70	
71	    /** The stored E.164 telephone formatted for humans (see {@link OwnerTelephones#toDisplay}). */
72	    default String telephoneDisplay(Owner owner) {
73	        return OwnerTelephones.toDisplay(owner.getTelephone());
74	    }
75	
76	    private static String initial(String name) {
77	        return Character.toUpperCase(name.charAt(0)) + ".";
78	    }
79	
80	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
81	     * last two digits of the fiscal year of the registrationDate (see {@link FiscalYear}). */
82	    default String membershipNumber(Owner owner) {
83	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
84	            return null;
85	        }
86	        return String.format("%s-M%02d", owner.getCustomerCode(), FiscalYear.of(owner.getRegistrationDate()) % 100);
87	    }
88	
89	    /** The owner's 'FY&lt;YY&gt;' fiscal year, derived from the business-day-adjusted
90	     * registrationDate (see {@link FiscalYear}), or null when the date is unknown. */
91	    default String fiscalYear(Owner owner) {
92	        return FiscalYear.label(owner.getRegistrationDate());
93	    }
94	
95	    /** The owner's membership points: starts at 0, plus 2 when an email is present, plus 1 when
96	     * namesakeCount is 0, plus 2 for a household of 3 or more, plus 3 when tenure is at least one
97	     * elapsed fiscal year. */
98	    default int membershipPoints(Owner owner) {
99	        int points = 0;
100	        if (hasEmail(owner)) {
101	            points += 2;
102	        }
103	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
104	            points += 1;
105	        }
106	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
107	            points += 2;
108	        }
109	        if (Tenure.fiscalYears(owner.getRegistrationDate()) >= 1) {
110	            points += 3;
111	        }
112	        return points;
113	    }
114	
115	    /** The owner's membership level from 1 to 4, derived from {@link #membershipPoints(Owner)}:
116	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more. */
117	    default int membershipLevel(Owner owner) {
118	        int points = membershipPoints(owner);
119	        if (points <= 1) {
120	            return 1;
121	        }
122	        if (points <= 3) {
123	            return 2;
124	        }
125	        if (points <= 5) {
126	            return 3;
127	        }
128	        return 4;
129	    }
130	
131	    /** The owner's canonical region: the REGION segment of the customer code (see
132	     * {@link CustomerCode}), or null when the customer code is unset. */
133	    default String locality(Owner owner) {
134	        return CustomerCode.region(owner.getCustomerCode());
135	    }
136	
137	    /** The owner's IANA timezone, derived from the locality/region via the pinned
138	     * region-to-timezone table (see {@link Locality#timezoneForRegion}), or null when the
139	     * region is not in the table. */
140	    default String timezone(Owner owner) {
141	        return Locality.timezoneForRegion(locality(owner));
142	    }
143	
144	    /** The owner's preferred contact channel: 'EMAIL' when an email is present, otherwise 'PHONE'. */
145	    default String contactPreference(Owner owner) {
146	        return hasEmail(owner) ? "EMAIL" : "PHONE";
147	    }
148	
149	    /** Whether the owner has a non-blank email. */
150	    private static boolean hasEmail(Owner owner) {
151	        return owner.getEmail() != null && !owner.getEmail().isBlank();
152	    }
153	
154	    /** The owner's derived identity key (see {@link OwnerIdentity}). */
155	    default String identityKey(Owner owner) {
156	        return OwnerIdentity.of(owner);
157	    }
158	
159	    /** The Luhn check digit over the digits of the owner's customer code, or null when unset. */
160	    default Integer checkDigit(Owner owner) {
161	        return owner.getCustomerCode() == null ? null : CheckDigit.luhn(owner.getCustomerCode());
162	    }
163	
164	    /** The owner's age band on their registration date, derived from their birth date (see
165	     * {@link AgeBand}), or null when either date is unset. */
166	    default String ageBand(Owner owner) {
167	        return AgeBand.on(owner.getBirthDate(), owner.getRegistrationDate());
168	    }
169	
170	    /** Whether the owner soft-matched an existing owner at creation, i.e. it has a
171	     * {@code possibleDuplicateOf} id. */
172	    default boolean possibleDuplicate(Owner owner) {
173	        return owner.getPossibleDuplicateOf() != null;
174	    }
