185	    Owner toOwner(OwnerFieldsDto ownerDto);
186	
187	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
188	
189	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
190	
