2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Locale;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.model.Sha256;
9	
10	/**
11	 * The single definition of what a "household" is: owners sharing the same last name and
12	 * postcode, compared case-insensitively with runs of whitespace collapsed to a single
13	 * space. The {@code householdId} is derived deterministically from those two fields, so
14	 * every owner with the same last name and postcode computes the same id automatically,
15	 * regardless of creation order or whether they opted in with {@code sharesHousehold}.
16	 *
17	 * <p>Shared by {@link RejectDuplicateOwnerHousehold} (which forbids an unopted duplicate),
18	 * {@link AssignOwnerHousehold} (which stamps the id) and {@link AssignOwnerHouseholdSize}
19	 * (which counts members), so all decide membership identically.
20	 */
21	final class OwnerHouseholds {
22	
23	    private static final int ID_HEX_LENGTH = 12;
24	
25	    private OwnerHouseholds() {
26	    }
27	
28	    /**
29	     * A stable identifier for the household of an owner with this {@code lastName} and
30	     * {@code postcode}: the first {@value #ID_HEX_LENGTH} hex characters of SHA-256 over
31	     * {@code normalizedLastName + '|' + postcode}. Every member computes the same value, so
32	     * it is deterministic and independent of creation order.
33	     */
34	    static String householdId(String lastName, String postcode) {
35	        String key = canonical(lastName) + "|" + trimmed(postcode);
36	        return Sha256.upperHex(key, ID_HEX_LENGTH);
37	    }
38	
39	    /**
40	     * The existing owners that belong to the household identified by {@code lastName} and
41	     * {@code postcode} — those whose own last name and postcode hash to the same
42	     * {@link #householdId}.
43	     */
44	    static List<Owner> members(Iterable<Owner> owners, String lastName, String postcode) {
45	        String householdId = householdId(lastName, postcode);
46	        List<Owner> members = new ArrayList<>();
47	        for (Owner existing : owners) {
48	            if (householdId.equals(householdId(existing.getLastName(), existing.getPostcode()))) {
49	                members.add(existing);
50	            }
51	        }
52	        return members;
53	    }
54	
55	    /** Trim, collapse internal whitespace to a single space, and lower-case for comparison. */
56	    private static String canonical(String value) {
57	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
58	    }
59	
60	    /** The trimmed value, or the empty string when absent. */
61	    private static String trimmed(String value) {
62	        return value == null ? "" : value.trim();
63	    }
64	}
