2	
3	import java.util.Locale;
4	import java.util.Objects;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	
11	/**
12	 * Flags a soft duplicate: a create that is not a hard duplicate (see
13	 * {@link RejectDuplicateOwnerHousehold}, which already let it through) but that shares an
14	 * existing owner's last name and postcode while carrying a <em>different</em> telephone. The
15	 * owner is still created; the response merely carries {@code possibleDuplicate}/
16	 * {@code possibleDuplicateOf} pointing at the matched owner.
17	 *
18	 * <p>A declared household member — one created with {@code sharesHousehold} — deliberately
19	 * shares an existing owner's last name and postcode, so it is <em>not</em> a suspected
20	 * duplicate and is left unflagged.
21	 *
22	 * <p>Runs after {@link BuildOwner} but before the owner is saved, so it compares against the
23	 * owners that existed before this create (and so never matches the owner being built), and
24	 * mutates the built {@link Owner} in place. When several owners match, the one with the lowest
25	 * id is reported, so the result is deterministic. Last names are compared case-insensitively
26	 * (as elsewhere, e.g. {@link AssignOwnerNamesakeCount}); postcode and telephone are compared in
27	 * their stored, normalized form.
28	 */
29	public class AssignOwnerPossibleDuplicate {
30	
31	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
32	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
33	            return; // a declared household member is not a suspected duplicate
34	        }
35	        String lastName = canonical(owner.getLastName());
36	        String postcode = trimmed(owner.getPostcode());
37	        String telephone = trimmed(owner.getTelephone());
38	        if (postcode == null) {
39	            return; // no postcode to share, so no soft match
40	        }
41	        Owner match = null;
42	        for (Owner existing : Owners.active(ownerRepository.findAll())) {
43	            if (lastName.equals(canonical(existing.getLastName()))
44	                    && postcode.equals(trimmed(existing.getPostcode()))
45	                    && !Objects.equals(telephone, trimmed(existing.getTelephone()))
46	                    && (match == null || existing.getId() < match.getId())) {
47	                match = existing;
48	            }
49	        }
50	        if (match != null) {
51	            owner.setPossibleDuplicateOf(match.getId());
52	        }
53	    }
54	
55	    private static String canonical(String value) {
56	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
57	    }
58	
59	    private static String trimmed(String value) {
60	        if (value == null) {
61	            return null;
62	        }
63	        String trimmed = value.trim();
64	        return trimmed.isEmpty() ? null : trimmed;
65	    }
66	}
